def invert_index(groups):
    result = []
    seen = {}
    for key, values in groups:
        for v in values:
            if v not in seen:
                seen[v] = [key]
                result.append([v, [key]])
            else:
                if key not in seen[v]:
                    seen[v].append(key)
                result[-1][1].append(key)
    return result

